fn open(path: &str) -> Result<Self> {
    let user_path = Path::new(path);
    if !user_path.is_absolute() {
        return Err("PUBLIC_HOST_KERNEL_PARENT".into());
    }
    let parent = fs::canonicalize(user_path)
        .map_err(|_| crate::Error::from("PUBLIC_HOST_KERNEL_PARENT"))?;
    // A strict systemd-owned *single parent*, not the common cgroup
    // root, any child/service, or a caller-created user.slice.
    if !approved_parent_path(&parent) || parent != user_path {
        return Err("PUBLIC_HOST_KERNEL_PARENT".into());
    }
    if !Path::new("/sys/fs/cgroup/cgroup.controllers").is_file() {
        return Err("PUBLIC_HOST_KERNEL_UNSUPPORTED".into());
    }
    let meta = fs::symlink_metadata(&parent)?;
    if !meta.is_dir() || meta.uid() != 0 || meta.permissions().mode() & 0o022 != 0 {
        return Err("PUBLIC_HOST_KERNEL_PARENT".into());
    }
    let boot = fs::read_to_string("/proc/sys/kernel/random/boot_id")
        .map_err(|_| crate::Error::from("PUBLIC_HOST_KERNEL_CONTEXT"))?;

/// The public V3 library and development CLI use the EXACT same eligibility.
pub const FIXED_PUBLIC_KERNEL_PARENT: &str = "/sys/fs/cgroup/trnmponpublic.slice";
/// Direct library callers cannot bypass the CLI's kernel-parent requirement.
/// A loopback test service needs no administrator privileges; an externally
/// reachable service must already be placed under the one fixed parent.
pub fn require_for_listener(
    address: std::net::SocketAddr,
) -> crate::Result<Option<HostKernelBudget>> {
    require_host_kernel_budget(
        address,
        (!address.ip().is_loopback()).then_some(FIXED_PUBLIC_KERNEL_PARENT),
    )
}

pub fn receive_public_page_from_before_observed(
    node: &mut Node,
    source: SocketAddr,
    page: Page,
    tip: Hash,
    after: Hash,
    clock: u64,
    deadline: Instant,
    observation: Option<&HistoryImportObserver>,
) -> Result<Hash> {
    use history_import::{observe_host, HistoryHostPhase};
    // The ORIGINAL fixed administrator-owned Host parent is required even
    // for a loopback source: a caller's socket address is not provenance.
    let kernel = observe_host(observation, HistoryHostPhase::Resolve, || {
        crate::host_kernel_parent::require_host_kernel_budget(
            source,
            Some(crate::host_kernel_parent::FIXED_PUBLIC_KERNEL_PARENT),
        )?
        .ok_or_else(|| crate::Error::from("PUBLIC_HOST_KERNEL_REQUIRED"))
    })?;
    observe_host(observation, HistoryHostPhase::Initial, || kernel.verify())?;
    let native = history_import::receive_observed(
        history_import::Owner::Exclusive(node),
        page,
        tip,
        after,
        clock,
        history_import::Control {
            deadline,
            resource: &|| {
                observe_host(observation, HistoryHostPhase::Checkpoint, || {
                    kernel.verify()
                })
            },
        },
        observation,
    );
    // Do not convert an already committed block into an invalid work proof
    // when the last local Host owner observation fails.
    history_import::finish_with_resource(native, deadline, || {
        observe_host(observation, HistoryHostPhase::Final, || kernel.verify())
    })
}
